// import-env.js
const fs = require('fs');
const path = require('path');

const ENV_FILE = path.resolve(__dirname, '.env.test');
const URL = 'http://localhost:3003/api/doc-export';

function parseEnv(fileContent) {
  const env = {};
  const lines = fileContent.split('\n');
  for (let line of lines) {
    line = line.trim();
    if (!line || line.startsWith('#')) continue;
    const idx = line.indexOf('=');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    let value = line.slice(idx + 1).trim();
    // strip surrounding quotes (single or double)
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith('\'') && value.endsWith('\''))) {
      value = value.slice(1, -1);
    }
    env[key] = value;
  }
  return env;
}

async function postEnv() {
  try {
    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const envObj = parseEnv(content);

    const response = await fetch(URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(envObj),
    });

    const result = await response.json();
    console.log('POST result:', result);
  } catch (err) {
    console.error('Error posting env:', err);
  }
}

